    if (!(cin >> N >> M)) return 0;

    if (N == 1) {
        cout << M << "\n";
        return 0;
    }

    vector<long long> S;
    S.reserve(N);

    // Generate first N - 1 ternary numbers using digits {0, 1}
    for (int i = 0; (int)S.size() < N - 1; ++i) {
        long long val = 0;
        long long power3 = 1;
        int temp = i;
        while (temp > 0) {
            if (temp & 1) {
                val += power3;
            }
            power3 *= 3;
            temp >>= 1;
        }
        S.push_back(val);
    }

    long long sum_S = 0;
    long long max_val = 0;
    for (long long x : S) {
        sum_S += x;
        max_val = max(max_val, x);
    }

    // Pick X > 2 * max_val such that X = (M - sum_S) mod N
    long long rem = (M - sum_S) % N;
    if (rem < 0) rem += N;

    long long X = 2 * max_val + 1;
    long long cur_rem = X % N;
    long long diff = (rem - cur_rem + N) % N;
    X += diff;

    S.push_back(X);
    sum_S += X;

    long long shift = (M - sum_S) / N;
    for (int i = 0; i < N; ++i) {
        S[i] += shift;
    }

    for (int i = 0; i < N; ++i) {
        cout << S[i] << (i == N - 1 ? "" : " ");
    }
    cout << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

struct Edge {
    int to;
    int i, j;
    int sgn; // +1 if moving forward (u < v), -1 if backward
};

int main() {
    int N, L, R;
    if (!(cin >> N >> L >> R)) return 0;

    int max_val = (1 << N);
    vector<int> dist(max_val + 1, -1);
    vector<int> parent_node(max_val + 1, -1);
    vector<pair<int, int>> parent_query(max_val + 1);
    vector<int> parent_sgn(max_val + 1, 0);

    queue<int> q;
    q.push(L);
    dist[L] = 0;

    int target = R + 1;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        if (u == target) break;

        for (int i = 0; i <= N; ++i) {
            int len = (1 << i);
            if (len > max_val) break;

            // Edge forward: u is j * len
            if (u % len == 0 && u + len <= max_val) {
                int v = u + len;
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    parent_node[v] = u;
                    parent_query[v] = {i, u / len};
                    parent_sgn[v] = 1;
                    q.push(v);
                }
            }
            // Edge backward: u is (j + 1) * len
            if (u % len == 0 && u - len >= 0) {
                int v = u - len;
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    parent_node[v] = u;
                    parent_query[v] = {i, v / len};
                    parent_sgn[v] = -1;
                    q.push(v);
                }
            }
        }
    }

    // Reconstruct path from target back to L
    vector<pair<pair<int, int>, int>> ops;
    int curr = target;
    while (curr != L) {
        ops.push_back({parent_query[curr], parent_sgn[curr]});
        curr = parent_node[curr];
    }
    reverse(ops.begin(), ops.end());

    int total_sum = 0;
    for (const auto& op : ops) {
        int i = op.first.first;
        int j = op.first.second;
        int sgn = op.second;

        cout << "? " << i << " " << j << endl;
        int res;
        cin >> res;
        if (res == -1) return 0;

        if (sgn == 1) {
            total_sum = (total_sum + res) % 100;
        } else {
            total_sum = (total_sum - res + 100) % 100;
        }
    }

    cout << "! " << total_sum << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

static const int MOD = 998244353;

struct SegTree {
    int size;
    vector<long long> v;
    SegTree(int n) {
        size = 1;
        while (size < n) size <<= 1;
        v.assign(size * 2, 0);
    }
    void add(int pos, long long x) {
        pos += size;
        v[pos] = (v[pos] + x) % MOD;
        pos >>= 1;
        while (pos >= 1) {
            v[pos] = (v[pos * 2] * v[pos * 2 + 1]) % MOD;
            pos >>= 1;
        }
    }
    long long query(int l, int r) {
        l += size;
        r += size;
        long long res = 1;
        while (l < r) {
            if (l & 1) {
                res = (res * v[l]) % MOD;
                l++;
            }
            if (r & 1) {
                r--;
                res = (res * v[r]) % MOD;
            }
            l >>= 1;
            r >>= 1;
        }
        return res;
    }
};

vector<long long> calc(int n, const vector<int>& p) {
    vector<int> level(n, n - 1);
    vector<int> sl;
    for (int i = 0; i < n; ++i) {
        while (!sl.empty() && sl.back() > p[i]) {
            sl.pop_back();
        }
        level[i] -= sl.size();
        sl.push_back(p[i]);
    }
    vector<int> sr;
    for (int i = n - 1; i >= 0; --i) {
        while (!sr.empty() && sr.back() > p[i]) {
            sr.pop_back();
        }
        level[i] -= sr.size();
        sr.push_back(p[i]);
    }

    vector<long long> power2(n + 1, 1);
    for (int i = 0; i < n; ++i) {
        power2[i + 1] = (power2[i] * 2) % MOD;
    }

    vector<long long> res(n, 0);
    for (int i = 0; i < n; ++i) {
        int c = (i == n - 1 || p[i] > p[i + 1]) + (i == 0 || p[i] > p[i - 1]);
        res[i] = (power2[level[i]] * c) % MOD;
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    long long H;
    if (!(cin >> N >> H)) return 0;

    vector<long long> X(N);
    for (int i = 0; i < N; ++i) {
        cin >> X[i];
    }

    vector<pair<long long, int>> pillars(N);
    for (int i = 0; i < N; ++i) {
        pillars[i] = {X[i], i};
    }
    sort(pillars.begin(), pillars.end());

    vector<int> p(N);
    for (int i = 0; i < N; ++i) {
        p[i] = pillars[i].second;
    }

    vector<long long> v;
    vector<int> g;
    int pre = 0;
    int m = 0;

    for (int i = 1; i <= N; ++i) {
        if (i == N || pillars[i].first - pillars[i - 1].first > H) {
            vector<int> sub_p(p.begin() + pre, p.begin() + i);
            vector<long long> sub_v = calc(i - pre, sub_p);
            for (long long val : sub_v) v.push_back(val);
            for (int k = pre; k < i; ++k) g.push_back(m);
            pre = i;
            m++;
        }
    }

    vector<int> pinv(N);
    for (int i = 0; i < N; ++i) {
        pinv[p[i]] = i;
    }

    SegTree seg(m);
    vector<long long> pref_res;
    pref_res.push_back(0);

    for (int idx : pinv) {
        seg.add(g[idx], v[idx]);
        pref_res.push_back(seg.query(0, m));
    }

    for (int i = 0; i < N; ++i) {
        long long ans = (pref_res[i + 1] - pref_res[i] + MOD) % MOD;
        cout << ans << (i == N - 1 ? "" : " ");
    }
    cout << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <algorithm>

using namespace std;

static short nxt_node[3005][3005];
static short dist_node[3005][3005];
static bool is_pal[3005][3005];

struct DSU {
    vector<int> parent;
    DSU(int n) {
        parent.resize(n + 1);
        for (int i = 0; i <= n; ++i) parent[i] = i;
    }
    int find(int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent[i]);
    }
    void unite(int i, int j) {
        int ri = find(i), rj = find(j);
        if (ri != rj) parent[ri] = rj;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    if (!(cin >> N)) return 0;

    vector<vector<int>> adj(N + 1);
    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<string> A(N + 1);
    for (int i = 1; i <= N; ++i) {
        cin >> A[i];
    }

    // BFS from each root to precompute dist and nxt
    for (int root = 1; root <= N; ++root) {
        for (int i = 1; i <= N; ++i) dist_node[root][i] = -1;
        dist_node[root][root] = 0;
        queue<int> q;
        q.push(root);
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int v : adj[u]) {
                if (dist_node[root][v] == -1) {
                    dist_node[root][v] = dist_node[root][u] + 1;
                    nxt_node[v][root] = u; // step from v towards root
                    q.push(v);
                }
            }
        }
    }

    DSU dsu(N);

    // Queue for forced palindromes
    vector<vector<bool>> in_q(N + 1, vector<bool>(N + 1, false));
    queue<pair<int, int>> q;

    for (int i = 1; i <= N; ++i) {
        for (int j = i + 1; j <= N; ++j) {
            if (A[i][j - 1] == '1') {
                in_q[i][j] = true;
                in_q[j][i] = true;
                q.push({i, j});
            }
        }
    }

    while (!q.empty()) {
        auto p = q.front();
        q.pop();
        int u = p.first;
        int v = p.second;
        dsu.unite(u, v);

        if (dist_node[u][v] >= 2) {
            int nu = nxt_node[u][v];
            int nv = nxt_node[v][u];
            if (!in_q[nu][nv]) {
                in_q[nu][nv] = true;
                in_q[nv][nu] = true;
                q.push({nu, nv});
            }
        }
    }

    // Group pairs by distance
    vector<vector<pair<int, int>>> pairs_by_dist(N);
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            pairs_by_dist[dist_node[i][j]].push_back({i, j});
        }
    }

    long long ans = 0;
    for (int d = 0; d < N; ++d) {
        for (const auto& pr : pairs_by_dist[d]) {
            int u = pr.first;
            int v = pr.second;
            if (d == 0) {
                is_pal[u][v] = true;
            } else if (d == 1) {
                is_pal[u][v] = (dsu.find(u) == dsu.find(v));
            } else {
                int nu = nxt_node[u][v];
                int nv = nxt_node[v][u];
                is_pal[u][v] = (dsu.find(u) == dsu.find(v)) && is_pal[nu][nv];
            }
            if (is_pal[u][v]) ans++;
        }
    }

    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

static const int MOD = 998244353;
static const int MAX = 2000005;

long long fact[MAX];
long long inv[MAX];

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

void precompute() {
    fact[0] = 1;
    inv[0] = 1;
    for (int i = 1; i < MAX; ++i) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    inv[MAX - 1] = power(fact[MAX - 1], MOD - 2);
    for (int i = MAX - 2; i >= 1; --i) {
        inv[i] = (inv[i + 1] * (i + 1)) % MOD;
    }
}

long long nCr(int n, int r) {
    if (r < 0 || r > n) return 0;
    return fact[n] * inv[r] % MOD * inv[n - r] % MOD;
}

void solve() {
    int N;
    if (!(cin >> N)) return;
    if (N == 2) {
        cout << 1 << "\n";
        return;
    }
    long long term1 = (1LL * (N + 1) * nCr(2 * N - 3, N - 1)) % MOD;
    long long term2 = (1LL * N * nCr(2 * N - 4, N - 2)) % MOD;
    long long ans = (term1 - term2 + MOD) % MOD;
    cout << ans << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    precompute();
    int T;
    if (cin >> T) {
        while (T--) solve();
    }
    return 0;
}

