    char ans;
    cin >> ans;
    return (ans == 'Y');
}

int main() {
    // 1. Check if power of 10
    if (ask(1000000000LL)) {
        for (int k = 0; k < 10; ++k) {
            long long val = 2;
            for (int i = 0; i < k; ++i) val *= 10;
            if (ask(val)) {
                long long ans = 1;
                for (int i = 0; i < k; ++i) ans *= 10;
                cout << "! " << ans << endl;
                return 0;
            }
        }
    } else {
        // Not a power of 10
        // Find length L
        int L = 1;
        long long cur = 10;
        for (int k = 1; k < 10; ++k) {
            if (!ask(cur)) {
                L = k;
                break;
            }
            cur *= 10;
        }

        // Binary search in [10^(L-1), 10^L - 1]
        long long low = 1;
        for (int i = 1; i < L; ++i) low *= 10;
        long long high = low * 10 - 1;
        long long ans = high;

        long long shift = 10;

        while (low <= high) {
            long long mid = low + (high - low) / 2;
            if (ask(mid * shift)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        cout << "! " << ans << endl;
        return 0;
    }
    return 0;
}

