int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    if (!(cin >> N)) return 0;

    vector<long long> A(N);
    long long sum_A = 0;
    for (int i = 0; i < N; ++i) {
        cin >> A[i];
        sum_A += A[i];
    }

    if (sum_A != 0) {
        cout << -1 << "\n";
        return 0;
    }

    vector<long long> P(N, 0);
    for (int i = 1; i < N; ++i) {
        P[i] = P[i - 1] + A[i - 1];
    }

    long long sum_P = 0;
    for (int i = 0; i < N; ++i) {
        sum_P += P[i];
    }

    if (sum_P % N != 0) {
        cout << -1 << "\n";
        return 0;
    }

    long long d1 = -(sum_P / N);
    vector<long long> d(N);
    d[0] = d1;
    for (int i = 1; i < N; ++i) {
        d[i] = d1 + P[i];
    }

    vector<long long> Q(N, 0);
    for (int i = 1; i < N; ++i) {
        Q[i] = Q[i - 1] + d[i];
    }

    long long min_Q = 0;
    for (int i = 0; i < N; ++i) {
        min_Q = min(min_Q, Q[i]);
    }

    long long x1 = (min_Q < 0 ? -min_Q : 0);
    long long total_ops = 0;
    for (int i = 0; i < N; ++i) {
        total_ops += (x1 + Q[i]);
    }

    cout << total_ops << "\n";
    return 0;
}
